    '''Steps over the statement.

    :param skip_list: *(Optional)* The skipList specifies location ranges that should be skipped on step over. *(EXPERIMENTAL)*
    '''
    params: T_JSON_DICT = {}
    if skip_list is not None:
        params['skipList'] = [i.to_json() for i in skip_list]
    yield {'method': 'Debugger.stepOver', 'params': params}


